export const catalogProducts: ProductDetail[] = catalogProductsData;
export const newInProducts: ProductDetail[] = newInProductsData;

const allProducts = [...catalogProductsData, ...newInProductsData];

export const getProductById = (id: number): ProductDetail | undefined => {
    return allProducts.find((product) => product.id === id);
};

export const toCatalogProduct = (product: ProductDetail): CatalogProduct => ({
    id: product.id,
    title: product.title,
    price: product.price,
    priceValue: product.priceValue,
    images: product.images,
    isNew: product.isNew,
    category: product.category,
    color: product.color,
    size: product.size,
    sortOrder: product.sortOrder,
});
